import{_ as e,o as i,c as r,aN as l}from"./chunks/framework.D31DlcCL.js";const d=JSON.parse('{"title":"AI大模型修仙传（序）：全系列10篇导读与大纲","description":"《AI大模型修仙传》全系列10篇导读，带你从基础概念、数学底层原理，一路通关到LangChain实战应用与终极哲学思考。","frontmatter":{"title":"AI大模型修仙传（序）：全系列10篇导读与大纲","date":"2026-04-01T00:00:00.000Z","categories":["AI"],"tags":["大模型","人工智能","学习路线"],"description":"《AI大模型修仙传》全系列10篇导读，带你从基础概念、数学底层原理，一路通关到LangChain实战应用与终极哲学思考。"},"headers":[],"relativePath":"posts/ai-series-0-index.md","filePath":"posts/ai-series-0-index.md","lastUpdated":null}'),t={name:"posts/ai-series-0-index.md"};function n(s,a,o,h,m,u){return i(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="ai大模型修仙传-全系列导读与大纲" tabindex="-1">AI大模型修仙传：全系列导读与大纲 <a class="header-anchor" href="#ai大模型修仙传-全系列导读与大纲" aria-label="Permalink to &quot;AI大模型修仙传：全系列导读与大纲&quot;">​</a></h1><p>各位道友，欢迎来到《AI大模型修仙传》系列！</p><p>在这个系列中，我们将用最通俗易懂、风趣幽默的“修仙”视角，结合图文与基础数学原理，带你从最底层的神经元（ANN），一路打通卷积（CNN）、循环序列（RNN），并最终参透当前大模型的核心命脉——Transformer架构与涌现能力。</p><p>不仅如此，我们还会手把手教你使用LangChain给大模型装上“四肢”和“外脑”，打造属于你自己的赛博管家，并在最后探讨关于硅基生命的终极哲学命题。</p><p>以下是全系列10篇文章的完整目录，建议收藏后按顺序“修炼”：</p><h3 id="第一卷-筑基篇-底层神经网络" tabindex="-1">第一卷：筑基篇（底层神经网络） <a class="header-anchor" href="#第一卷-筑基篇-底层神经网络" aria-label="Permalink to &quot;第一卷：筑基篇（底层神经网络）&quot;">​</a></h3><ul><li><a href="./ai-series-1-ann.html"><strong>第一篇：神经元与ANN——AI的“细胞”是怎么思考的？</strong></a><ul><li><em>简介</em>：感知机、权重、偏置与激活函数的最强白话解释。</li></ul></li><li><a href="./ai-series-2-cnn.html"><strong>第二篇：CNN——AI是怎么看懂猫猫狗狗的？</strong></a><ul><li><em>简介</em>：揭秘卷积操作与池化层，看懂AI的“火眼金睛”。</li></ul></li><li><a href="./ai-series-3-rnn.html"><strong>第三篇：RNN与LSTM——AI怎么拥有“短时记忆”？</strong></a><ul><li><em>简介</em>：解决序列数据的痛点，揭秘梯度消失与LSTM的三大门控机制。</li></ul></li></ul><h3 id="第二卷-飞升篇-transformer与大模型" tabindex="-1">第二卷：飞升篇（Transformer与大模型） <a class="header-anchor" href="#第二卷-飞升篇-transformer与大模型" aria-label="Permalink to &quot;第二卷：飞升篇（Transformer与大模型）&quot;">​</a></h3><ul><li><a href="./ai-series-4-transformer-attention.html"><strong>第四篇：Transformer上篇——“Attention Is All You Need”到底有多神？</strong></a><ul><li><em>简介</em>：QKV矩阵与Self-Attention（自注意力机制）的硬核数学原理科普。</li></ul></li><li><a href="./ai-series-5-transformer-architecture.html"><strong>第五篇：Transformer下篇——位置编码与大模型的“奇经八脉”</strong></a><ul><li><em>简介</em>：补全拼图，解析多头注意力、位置编码与前馈神经网络。</li></ul></li><li><a href="./ai-series-6-llm-evolution.html"><strong>第六篇：从GPT到LLM——为什么参数大了就能“涌现”智能？</strong></a><ul><li><em>简介</em>：预训练、微调（SFT/RLHF）、Scaling Laws与神秘的“涌现”现象。</li></ul></li></ul><h3 id="第三卷-炼器实战篇-langchain应用" tabindex="-1">第三卷：炼器实战篇（LangChain应用） <a class="header-anchor" href="#第三卷-炼器实战篇-langchain应用" aria-label="Permalink to &quot;第三卷：炼器实战篇（LangChain应用）&quot;">​</a></h3><ul><li><a href="./ai-series-7-langchain-basics.html"><strong>第七篇：LangChain初探——给大模型装上“四肢”和“工具箱”</strong></a><ul><li><em>简介</em>：告别“缸中之脑”，解析Prompts、Chains、Memory与Agents。</li></ul></li><li><a href="./ai-series-8-rag-vector-db.html"><strong>第八篇：RAG与向量数据库——怎么让AI不再“胡说八道”？</strong></a><ul><li><em>简介</em>：治好大模型的“幻觉”，揭秘Embeddings与知识库外挂。</li></ul></li><li><a href="./ai-series-9-langchain-agents.html"><strong>第九篇：魔法实战——用LangChain打造你的专属赛博管家</strong></a><ul><li><em>简介</em>：代码实战，让AI自己上网搜索、发邮件，成为你的专属打工人。</li></ul></li></ul><h3 id="第四卷-论道篇-终极哲学" tabindex="-1">第四卷：论道篇（终极哲学） <a class="header-anchor" href="#第四卷-论道篇-终极哲学" aria-label="Permalink to &quot;第四卷：论道篇（终极哲学）&quot;">​</a></h3><ul><li><a href="./ai-series-10-future-reflections.html"><strong>第十篇：终极思考——硅基生命会梦到电子羊吗？</strong></a><ul><li><em>简介</em>：探讨大模型的心魔（AI对齐）、常识鸿沟（莫拉维克悖论）与硅基未来的终极拷问。</li></ul></li></ul><hr><p>准备好你的键盘和脑细胞，我们现在就踏上这条AI修仙之路！</p>',15)])])}const c=e(t,[["render",n]]);export{d as __pageData,c as default};
